function draftFromSource(source: CalendarSource) { const start = { versionId: source.start.versionId, revision: source.start.revision, date: source.start.date }; return source.kind === "duration" || source.kind === "window" ? { kind: source.kind, start, end: { versionId: source.end!.versionId, revision: source.end!.revision, date: source.end!.date } } : { kind: source.kind, start }; }

const known = (year: number) => ({ version: 1 as const, scale: "world-year" as const, kind: "known" as const, year });
const participant = (targetId: string, role: string) => ({ targetId, role, authoredReference: "", account: "An attributed saved connection" });
const comparable = (draft: LoreDraft) => ({ ...draft, historyRefs: [...draft.historyRefs].sort((a, b) => a.entityId.localeCompare(b.entityId)), milestones: [...draft.milestones].sort((a, b) => (a.entryId ?? "").localeCompare(b.entryId ?? "")) });
async function signIn(context: BrowserContext, base: string, user = "world-god") {
  const response = await context.request.post(`${base}/api/auth/sign-in/email`, { headers: { Origin: base }, data: { email: `${user}@example.invalid`, password: "Worlds-Test-Only-Password!" } });
  assert.equal(response.status(), 200, await response.text());
}
async function fits(page: Page) {
  await page.evaluate(() => new Promise<void>(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));
  assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1 && [...document.querySelectorAll<HTMLDialogElement>("dialog[open]")].every(d => d.scrollWidth <= d.clientWidth + 1)), "Workshop fits viewport width");
  const save = await page.getByRole("dialog").getByRole("button", { name: "Save record", exact: true }).boundingBox();
  assert.ok(save && save.y >= 0 && save.y + save.height <= page.viewportSize()!.height + 1, "Save footer stays reachable");
  const content = await page.getByRole("dialog").locator('[class*="creator-workshop"][class*="content"]').boundingBox();
  assert.ok(content && content.height >= 44, "Central content retains usable scrolling space");
}

